/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it, however deep the
 * chain. A deleted comment keeps its place as a placeholder (its text
 * blanked) so replies anchored to it — directly or through other deleted
 * replies — stay put.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const byId = new Map(decorated.map((comment) => [comment.id, comment]));

  function rootIdOf(comment: CommentWithAuthor): string {
    let current = comment;
    while (current.parentId !== null) {
      const parent = byId.get(current.parentId);
      if (!parent) break;
      current = parent;
    }
    return current.id;
  }

  const repliesByRoot = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const rootId = rootIdOf(comment);
    const bucket = repliesByRoot.get(rootId) ?? [];
    bucket.push(maskIfDeleted(comment));
    repliesByRoot.set(rootId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment: maskIfDeleted(comment),
      replies: repliesByRoot.get(comment.id) ?? [],
    }));
}

/** A deleted comment keeps its slot in the thread but loses its text. */
function maskIfDeleted(comment: CommentWithAuthor): CommentWithAuthor {
  return comment.archivedAt === null ? comment : { ...comment, body: "" };
}

