  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const watchers = new Set<UserId>();
  if (issue) {
    watchers.add(issue.authorId);
    if (issue.assigneeId) watchers.add(issue.assigneeId);
  }
  if (payload.parentId) {
    const parent = await commentRepo.findCommentById(
      payload.orgId,
      payload.parentId,
    );
    if (parent) watchers.add(parent.authorId);
  }

  // A mention alert takes precedence: anyone mentioned gets that alert
  // instead of the plain "comment added" one, never both.
  for (const mentioned of payload.mentionedUserIds) {
    watchers.delete(mentioned);
  }

  await notify(payload.orgId, "comment_created", [...watchers], {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    await notify(
      payload.orgId,
      "comment_mention",
      payload.mentionedUserIds,
      {
        title: "You were mentioned",
        body: `You were mentioned on issue ${payload.issueId}`,
        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

subscribe("comment.updated", async (payload) => {
  if (payload.newlyMentionedUserIds.length === 0) return;

  await notify(
    payload.orgId,
    "comment_mention",
    payload.newlyMentionedUserIds,
    {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    },
  );
});

