/**
 * One audit row per domain event; day grouping.
 *
 * Owner C implements `@/server/services/activity-service`, which subscribes to
 * the event bus at module init.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/server/repositories/activity-repository", async (importOriginal) => {
  const actual =
    await importOriginal<typeof import("@/server/repositories/activity-repository")>();
  return { ...actual, insertActivity: vi.fn(actual.insertActivity) };
});

import { emit, subscribe, subscriberCount } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import {
  exportActivity,
  groupByDay,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ActivityEvent } from "@/types/activity";
import type { CommentId, IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("activity", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  vi.mocked(activityRepo.insertActivity).mockClear();
});

describe("services/activity-service", () => {
  // subscribe() is registered for each ActivityAction-shaped event type.
  it("subscribes to every event that maps to an ActivityAction", () => {
    const before = subscriberCount("project.created");
    const off = registerActivityListeners();

    // registerActivityListeners() is idempotent per call — each call attaches
    // its own listener set, so calling it a second time adds one more.
    expect(subscriberCount("project.created")).toBe(before + 1);
    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("billing.plan_changed")).toBeGreaterThanOrEqual(1);

    off();
    expect(subscriberCount("project.created")).toBe(before);
  });

  // One emit produces exactly one activity row, with the actor and subject.
  it("records one audit row per emitted event", async () => {
    await emit("project.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: tenant.org.createdAt,
      projectId: tenant.project.id,
      name: "Audited project",
      slug: "audited-project",
    });

    const page = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      orgId: tenant.org.id,
      action: "project.created",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
    });
  });

  // A second identical emit produces a second row — the log is append-only.
  it("appends rather than de-duplicates repeated events", async () => {
    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: tenant.org.createdAt,
      projectId: tenant.project.id,
      name: "Repeat project",
      slug: "repeat-project",
    } as const;

    const before = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 100,
      cursor: null,
    });

    await emit("project.created", payload);
    await emit("project.created", payload);

    const after = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["project.created"],
      limit: 100,
      cursor: null,
    });

    expect(after.total).toBe(before.total + 2);
  });

  // A throwing repository must not fail the emit for sibling subscribers.
  it("isolates a write failure from the emitting service", async () => {
    vi.mocked(activityRepo.insertActivity).mockRejectedValueOnce(
      new Error("activity store unavailable"),
    );

    const sibling = vi.fn();
    const offSibling = subscribe("comment.created", sibling);

    await expect(
      emit("comment.created", {
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        occurredAt: tenant.org.createdAt,
        commentId: "cmt-isolation" as CommentId,
        issueId: "issue-isolation" as IssueId,
        mentionedUserIds: [],
      }),
    ).resolves.toBeUndefined();

    expect(sibling).toHaveBeenCalledTimes(1);
    offSibling();
  });

  // groupByDay buckets rows into ActivityGroup entries keyed by calendar day.
  it("groups the feed into calendar days", () => {
    const orgId = tenant.org.id;
    const build = (id: string, day: string): ActivityEvent => ({
      id: id as ActivityEvent["id"],
      orgId,
      action: "issue.created",
      actorId: null,
      subjectKind: "issue",
      subjectId: "s1",
      projectId: null,
      summary: "Created issue",
      metadata: {},
      occurredAt: `${day}T10:00:00.000Z` as ActivityEvent["occurredAt"],
    });

    const groups = groupByDay([
      build("e1", "2026-01-01"),
      build("e2", "2026-01-02"),
      build("e3", "2026-01-01"),
    ]);

    expect(groups).toHaveLength(2);
    expect(groups[0]?.day).toBe("2026-01-02");
    expect(groups[0]?.events).toHaveLength(1);
    expect(groups[1]?.day).toBe("2026-01-01");
    expect(groups[1]?.events).toHaveLength(2);
  });

  // Rows are scoped to the actor's org, and export needs activity:export.
  it("scopes the feed to the actor's organization", async () => {
    const other = await createTenant("activity-other", "growth");

    await expect(
      listActivity(other.actors.owner, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);

    // Exporting the audit log needs activity:export, which only admin+ holds.
    await expect(
      exportActivity(tenant.actors.member, {
        orgId: tenant.org.id,
        since: tenant.org.createdAt,
        until: tenant.org.createdAt,
        format: "json",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: tenant.org.createdAt,
        until: tenant.org.createdAt,
        format: "json",
      }),
    ).resolves.toEqual(expect.any(String));
  });
});

/**
 * Fan-out honours preferences and the digest flag.
 *
 * Owner C implements `@/server/services/notification-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  listNotifications,
  notify,
  resolveChannels,
} from "@/server/services/notification-service";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("notify", "growth");
});

afterAll(() => {
  cleanup();
});

describe("services/notification-service", () => {
  // comment.created with mentions produces one comment_mention per mentioned user.
  it("creates one notification per mentioned user", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mentions-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
